import './App.css';
import TelaInicialProjeto from './componentes/TelaInicialProjeto';
import TelaJogando from './componentes/TelaJogando';
import TelaFimdeJogo from './componentes/TelaFimdeJogo';
import { useEffect, useCallback, useState } from "react";
import { palavrasLista } from "./Util/Word";

const estagios = [
  { id: 1, nome: "ini" },
  { id: 2, nome: "Jogando" },
  { id: 3, nome: "Fimjogo" }
];

function App() {
  const [estagioJogo, setEstagioJogo] = useState(estagios[0].nome);
  const [palavrasJogo] = useState(palavrasLista);
  const [obterPalavraJogo, setObterPalavraJogo] = useState("");
  const [obterCategoriaJogo, setObterCategoriaJogo] = useState("");
  const [letrasJogo, setLetrasJogo] = useState([]);
  const [letrasAdivinhadas, setLetrasAdivinhadas] = useState([]);
  const [letrasErradas, setLetrasErradas] = useState([]);
  const [tentativas, setTentativas] = useState(3);
  const [pontuacao, setPontuacao] = useState(0);

  const reiniciarVariaveisJogo = () => {
    setLetrasAdivinhadas([]);
    setLetrasErradas([]);
  };

  useEffect(() => {
    if (tentativas <= 0) {
      reiniciarVariaveisJogo();
      setEstagioJogo(estagios[2].nome);
    }
  }, [tentativas]);

  const gameOverRetry = () => {
    setTentativas(15);
    setPontuacao(0);
    setEstagioJogo(estagios[0].nome);
  };

  const funcaoCarregarPalavraeCategoria = useCallback(() => {
    const listaCategorias = Object.keys(palavrasJogo);
    const categoria = listaCategorias[Math.floor(Math.random() * listaCategorias.length)];
    const palavraLocal = palavrasJogo[categoria][Math.floor(Math.random() * palavrasJogo[categoria].length)];
    return { categoria, palavraLocal };
  }, [palavrasJogo]);

  const funcaoIniciarJogo = useCallback(() => {
    const { categoria, palavraLocal } = funcaoCarregarPalavraeCategoria();
    const vetorPalavra = palavraLocal.split("").map((letra) => letra.toLowerCase());
    setObterCategoriaJogo(categoria);
    setObterPalavraJogo(palavraLocal);
    setLetrasJogo(vetorPalavra);
    setEstagioJogo(estagios[1].nome);
  }, [funcaoCarregarPalavraeCategoria]);

  useEffect(() => {
    const letrasUnicas = [...new Set(letrasJogo)];
    if (letrasUnicas.length === letrasAdivinhadas.length) {
      setPontuacao((valorAtual) => valorAtual + 50);
      reiniciarVariaveisJogo();
      funcaoIniciarJogo();
    }
  }, [letrasAdivinhadas, funcaoIniciarJogo, letrasJogo]);

  const funcaoProcessarLetraJogo = (letraDigitada) => {
    if (!letraDigitada || letraDigitada.length === 0) return;

    const letraNormalizada = letraDigitada.toLowerCase();

    if (letrasAdivinhadas.includes(letraNormalizada) || letrasErradas.includes(letraNormalizada)) {
      return;
    }

    if (letrasJogo.includes(letraNormalizada)) {
      setLetrasAdivinhadas((valorAtual) => [...valorAtual, letraNormalizada]);
      setPontuacao((ponto) => ponto + 5);
    } else {
      setLetrasErradas((valorAtual) => [...valorAtual, letraNormalizada]);
      setTentativas((ten) => ten - 1);
    }
  };

  return (
    <div className="App">
      {estagioJogo === "ini" && <TelaInicialProjeto iniciarJogo={funcaoIniciarJogo} />}
      {estagioJogo === "Jogando" && (
        <TelaJogando
          processarLetraJogo={funcaoProcessarLetraJogo}
          pontuacao={pontuacao}
          obterCategoriaJogo={obterCategoriaJogo}
          tentativas={tentativas}
          letrasAdivinhadas={letrasAdivinhadas}
          letrasJogo={letrasJogo}
          letrasErradas={letrasErradas}
        />
      )}
      {estagioJogo === "Fimjogo" && (
        <TelaFimdeJogo
          gameOverRetry={gameOverRetry}
          pontuacao={pontuacao}
        />
      )}
    </div>
  );
}

export default App;
